        if '+' in version:
            version_part, build = version.rsplit('+', 1)
        else:
            version_part = version
            build = None

        # Split pre-release (after -)
        if '-' in version_part:
            core, prerelease = version_part.split('-', 1)
        else:
            core = version_part
            prerelease = None

        # Parse core version (MAJOR.MINOR.PATCH)
        parts = core.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        prerelease_identifiers = []
        if prerelease:
            identifiers = prerelease.split('.')
            for identifier in identifiers:
                if identifier.isdigit():
                    prerelease_identifiers.append((0, int(identifier)))
                else:
                    prerelease_identifiers.append((1, identifier))

        return (major, minor, patch, prerelease_identifiers)

    def compare_key(version):
        major, minor, patch, prerelease_identifiers = parse_version(version)

        # For sorting:
        # - Compare (major, minor, patch) numerically
        # - If prerelease exists, it sorts before non-prerelease
        # - Prerelease identifiers are compared as tuples (all-digit before others, then value)

        if prerelease_identifiers:
            # Has prerelease: comes before non-prerelease
            return (major, minor, patch, (0, prerelease_identifiers))
        else:
            # No prerelease: comes after prerelease of same version
            return (major, minor, patch, (1,))

    # Sort with stable sort to preserve input order for equal precedence
    return sorted(versions, key=compare_key)

